import unittest
from candidate import longest

class TestLongestString(unittest.TestCase):
    def test_empty_list(self):
        self.assertIsNone(longest([]))

    def test_single_element_list(self):
        self.assertEqual(longest(['a']), 'a')

    def test_all_strings_equal_length(self):
        self.assertEqual(longest(['abc', 'def', 'ghi']), 'abc')

    def test_multiple_strings_same_max_length(self):
        self.assertEqual(longest(['a', 'bb', 'ccc']), 'a')

    def test_varying_string_lengths(self):
        self.assertEqual(longest(['a', 'bb', 'ccc', 'd', 'eee', 'fffff']), 'fffff')

    def test_empty_strings(self):
        self.assertEqual(longest(['', 'a', 'bb', '']), 'a')

    def test_mixed_characters(self):
        self.assertEqual(longest(['a1', 'b2b', 'c3c3', 'd4d4d4']), 'd4d4d4')

    def test_longest_string_at_end(self):
        self.assertEqual(longest(['a', 'bb', 'ccc', 'd', 'eee', 'f']), 'f')

    def test_longest_string_at_start(self):
        self.assertEqual(longest(['zzzz', 'a', 'bb', 'ccc']), 'zzzz')

    def test_none_input(self):
        self.assertIsNone(longest(None))

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            longest("not_a_list")

    def test_non_string_elements(self):
        with self.assertRaises(TypeError):
            longest([1, 2, 3])

    def test_strings_with_special_characters(self):
        self.assertEqual(longest(['@', '@@', '@@@@', '@@@@@']), '@@@@@')

    def test_strings_with_unicode(self):
        self.assertEqual(longest(['α', 'αβ', 'αβγ']), 'αβγ')
